<template>
  <RoomSlidePanel v-model="open" :label="t('talents.title')" class="talents-ui room-talents-viewer">
    <v-card class="room-talents-viewer__talent-viewer">
      <v-card-title class="talent-popup__heading room-talents-viewer__talent-viewer-heading"><span class="talent-popup__icon"><v-icon icon="mdi-source-branch" size="30" /></span><div><div class="talents-ui__eyebrow">{{ t('talents.design.progression') }}</div><h2>{{ t('talents.title') }}</h2></div><span v-if="unlockNotice" class="room-talents-viewer__talent-unlock-notice" role="status" :title="unlockNotice">{{ unlockNotice }}</span><AppCloseButton @click="open = false" /></v-card-title>
      <v-divider />
      <v-card-text class="room-talents-viewer__talent-viewer-body">

        <div v-if="snapshot?.settings.enabled" class="room-talents-viewer__layout">
          <nav class="room-talents-viewer__talent-tree-navigation" :aria-label="t('talents.title')">
            <div class="room-talents-viewer__talent-navigation-heading"><span class="talents-ui__eyebrow">{{ t('talents.design.yourTrees') }}</span><span>{{ visibleTrees.length.toString().padStart(2, '0') }}</span></div>
            <div class="room-talents-viewer__talent-navigation-list"><div v-for="{ tree: item, depth, hasChildren } in navigationTrees" :key="item.id" class="room-talents-viewer__talent-tree-nav-row" :data-depth="depth" :style="{ '--room-talents-viewer-talent-tree-nav-row-padding-left': Math.min(depth, 3) * 12 + 'px' }"><button v-if="hasChildren" type="button" class="room-talents-viewer__talent-tree-collapse" :aria-expanded="!collapsedTrees.has(item.id)" :aria-label="t(collapsedTrees.has(item.id) ? 'talents.progression.expand' : 'talents.progression.collapse', { name: item.name })" @click="toggleTree(item.id)"><v-icon :icon="collapsedTrees.has(item.id) ? 'mdi-chevron-right' : 'mdi-chevron-down'" size="16" /></button><button type="button" class="room-talents-viewer__talent-nav-item" :class="{ 'room-talents-viewer__talent-nav-item--active': selected === item.id }" :aria-current="selected === item.id ? 'page' : undefined" @click="selectTree(item.id)"><strong class="room-talents-viewer__talent-nav-title" :title="item.name">{{ item.name }}</strong><span class="room-talents-viewer__talent-nav-meta"><span class="room-talents-viewer__talent-nav-icon"><TalentImage :room-id="roomId" :image-id="item.imageId" :icon="item.icon" /></span><span class="room-talents-viewer__talent-nav-copy"><small>{{ investedPoints(item) }} {{ t('talents.design.pointsInvested') }}</small><span class="room-talents-viewer__talent-nav-progress"><span class="room-talents-viewer__nav-progress-fill" :style="{ '--room-talents-viewer-nav-progress-fill-width': (totalLevels(item) ? acquiredRanks(item) / totalLevels(item) * 100 : 0) + '%' }" /></span></span><span v-if="availablePoints(item) > 0" class="room-talents-viewer__talent-unspent-badge" :aria-label="t('talents.unspent')"><v-icon icon="mdi-plus" size="11" />{{ availablePoints(item) }}</span></span></button></div></div>
            <div v-if="tree" class="room-talents-viewer__talent-wallets" :aria-label="t('talents.unspent')">
              <div v-if="snapshot.settings.globalEnabled && tree.currency !== 'tree'" class="room-talents-viewer__talent-wallet"><v-icon icon="mdi-circle-multiple-outline" size="16" /><span><strong>{{ snapshot.player.global }}</strong><small>{{ t('talents.global') }}</small></span></div>
              <div v-if="tree.currency !== 'global'" class="room-talents-viewer__talent-wallet"><TalentImage :room-id="roomId" :image-id="tree.imageId" :icon="tree.icon" class="room-talents-viewer__point-icon" /><span><strong>{{ snapshot.player.trees[tree.id] ?? 0 }}</strong><small>{{ t('talents.treePoints') }}</small></span></div>
            </div>
            <div class="room-talents-viewer__talent-navigation-note"><v-icon icon="mdi-cursor-default-click-outline" size="20" /><p>{{ t('talents.design.viewerHint') }}</p></div>
          </nav>
          <main v-if="tree" class="room-talents-viewer__main">
            <p v-if="tree.description" class="room-talents-viewer__talent-tree-description">{{ tree.description }}</p>
            <section v-if="tree.options.selectSubtree && !progress?.selectedSubtree" class="room-talents-viewer__talent-specialization"><div class="talent-empty"><v-icon icon="mdi-compass-rose" size="42" /><h3>{{ t('talents.choose') }}</h3><p>{{ t('talents.design.specializationHint') }}</p></div><div class="room-talents-viewer__talent-specialization-grid"><article v-for="subtree in tree.subtrees" :key="subtree.id" class="room-talents-viewer__talent-specialization-card"><span class="room-talents-viewer__talent-specialization-icon"><TalentImage :room-id="roomId" :image-id="subtree.imageId" :icon="subtree.icon" /></span><h4>{{ subtree.name }}</h4><p>{{ subtree.description }}</p><v-btn color="primary" variant="tonal" append-icon="mdi-arrow-right" :disabled="service.state.busy" @click="service.mutate({ op: 'select', treeId: tree.id, subtreeId: subtree.id })">{{ t('talents.choose') }}</v-btn></article></div></section>
            <div v-else class="room-talents-viewer__talent-play-workspace">
              <div class="room-talents-viewer__talent-play-graph"><TalentCanvas :key="tree.id" :tree="tree" :room-id="roomId" :states="snapshot.states[tree.id]" :linked-trees="visibleTrees" :selected="nodeId" @select="nodeId = $event" @open-tree="selectTree" @allocate="allocate" @revert="revert">
                <template #heading-details><span class="room-talents-viewer__talent-build-summary"><span aria-hidden="true">·</span><v-icon icon="mdi-star-four-points-outline" size="14" />{{ investedPoints(tree) }} {{ t('talents.design.pointsInvested') }}</span></template>
                <template #toolbar-end><v-btn v-if="tree.options.allowRespec" variant="text" size="small" prepend-icon="mdi-restore" :disabled="service.state.busy" @click="respec(false)">{{ t('talents.respec') }}</v-btn><v-btn v-if="tree.options.selectSubtree && tree.options.allowSpecializationRespec" variant="text" size="small" prepend-icon="mdi-swap-horizontal" :disabled="service.state.busy" @click="respec(true)">{{ t('talents.changeSpecialization') }}</v-btn></template>
              </TalentCanvas><div class="room-talents-viewer__talent-graph-legend"><span><i class="room-talents-viewer__legend-dot room-talents-viewer__legend-dot--available" />{{ t('talents.design.available') }}</span><span><v-icon icon="mdi-circle-half-full" size="14" class="room-talents-viewer__legend-partial" />{{ t('talents.design.inProgress') }}</span><span><v-icon icon="mdi-check-decagram-outline" size="14" />{{ t('talents.design.mastered') }}</span></div></div>
              <aside class="room-talents-viewer__talent-detail-panel" :aria-label="t('talents.design.talentDetails')" aria-live="polite">
                <template v-if="node"><div class="room-talents-viewer__talent-detail-content"><div class="room-talents-viewer__talent-detail-heading"><span class="talents-ui__eyebrow">{{ t('talents.design.talentDetails') }}</span><v-chip size="x-small" variant="tonal" :color="state?.level === node.levels.length ? 'primary' : undefined">{{ t('talents.level') }} {{ state?.level ?? 0 }}/{{ node.levels.length }}</v-chip></div><div class="room-talents-viewer__talent-detail-emblem" :style="talentColorStyle(node.color)" :data-category="node.category ?? 'passive'" :class="{ 'room-talents-viewer__talent-detail-emblem--acquired': (state?.level ?? 0) > 0 }"><TalentImage :room-id="roomId" :image-id="node.imageId" :icon="node.icon" /><v-icon v-if="state?.level === node.levels.length" class="room-talents-viewer__talent-detail-complete" icon="mdi-check-decagram" size="24" /></div><h4>{{ node.name }}</h4><div class="room-talents-viewer__talent-rank-track" :style="talentColorStyle(node.color)" :aria-label="t('talents.level') + ' ' + (state?.level ?? 0) + '/' + node.levels.length"><span class="room-talents-viewer__rank" v-for="rank in Math.min(node.levels.length, 20)" :key="rank" :class="{ 'room-talents-viewer__rank--filled': rank <= (state?.level ?? 0) }" /></div><v-chip size="x-small" variant="tonal" class="room-talents-viewer__talent-category-detail" :prepend-icon="node.category === 'active' ? 'mdi-lightning-bolt' : 'mdi-shield-outline'">{{ t('talents.progression.' + (node.category ?? 'passive')) }}</v-chip><v-btn v-if="node.linkedTreeId && visibleTrees.some(tree => tree.id === node?.linkedTreeId)" size="small" variant="text" color="primary" append-icon="mdi-open-in-new" @click="selectTree(node.linkedTreeId!)">{{ t('talents.progression.openTree') }}</v-btn><p class="room-talents-viewer__node-description">{{ node.description || t('talents.design.noDescription') }}</p><div v-if="state?.reason" class="room-talents-viewer__talent-requirement-status" :class="{ 'room-talents-viewer__talent-requirement-status--mastered': state.reason === 'maximum' }"><v-icon :icon="state.reason === 'maximum' ? 'mdi-check-decagram-outline' : 'mdi-lock-outline'" size="17" /><span>{{ t('talents.reasons.' + state.reason) }}</span></div><TalentRequirements v-if="state?.reason === 'prerequisites'" :state="state" /><p v-if="state?.dependents.length" class="room-talents-viewer__talent-dependents">{{ t('talents.dependentTalents') }}: {{ state.dependents.join(', ') }}</p></div><div class="room-talents-viewer__talent-detail-actions"><v-btn color="primary" variant="flat" block :disabled="service.state.busy || !state?.canAllocate" :aria-label="t('talents.allocate')" :aria-description="(state?.cost ?? 1) === 0 ? t('talents.progression.free') : t('talents.progression.cost', { cost: state?.cost ?? 1 })" prepend-icon="mdi-plus" @click="allocate(node.id)">{{ t('talents.allocate') }} · {{ (state?.cost ?? 1) === 0 ? t('talents.progression.free') : (state?.cost ?? 1) }}</v-btn><v-btn variant="text" block :disabled="service.state.busy || !state?.canRevert" prepend-icon="mdi-minus" @click="revert(node.id)">{{ t('talents.revert') }}</v-btn></div></template>
                <div v-else class="talent-empty room-talents-viewer__talent-detail-empty"><div class="room-talents-viewer__talent-detail-placeholder"><v-icon icon="mdi-star-four-points-outline" size="32" /></div><h3>{{ t('talents.design.discoverTalent') }}</h3><p>{{ t('talents.design.selectTalentHint') }}</p></div>
              </aside>
            </div>
          </main>
          <div v-else class="talent-empty room-talents-viewer__talent-no-trees"><v-icon icon="mdi-source-branch" size="52" /><h3>{{ t('talents.empty') }}</h3><p>{{ t('talents.design.emptyViewerHint') }}</p></div>
        </div>
        <div v-else class="talent-empty"><v-icon icon="mdi-source-branch" size="48" /><h3>{{ t('talents.reasons.disabled') }}</h3></div>
      </v-card-text>
    </v-card>
  </RoomSlidePanel>
</template>
<script setup lang="ts">
import AppCloseButton from '@/shared/ui/AppCloseButton.vue';
import '@/assets/styles/features/rooms/talents/talent-ui.scss';
import { computed, ref, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import { spent, treeAccessible, talentTreeRows } from '@shared/rooms/talents';
import { emptyTalentProgress } from '@shared/rooms/talents.types';
import { talentRoom } from '@/features/rooms/services/talents.service';
import type { TalentTree } from '@shared/rooms/talents.types';
import RoomSlidePanel from '@/features/rooms/components/RoomSlidePanel.component.vue';
import TalentCanvas from '@/features/rooms/components/talents/TalentCanvas.component.vue';
import TalentRequirements from '@/features/rooms/components/talents/TalentRequirements.component.vue';
import { talentColorStyle } from '@/features/rooms/components/talents/talent-colors';
import TalentImage from '@/features/rooms/components/talents/TalentImage.component.vue';
const props = defineProps<{ roomId: string; userId: string }>(); const open = defineModel<boolean>({ default: false });
const { t } = useI18n(), service = talentRoom(props.roomId, props.userId), snapshot = computed(() => service.state.snapshot);
const selected = ref<string | null>(null), nodeId = ref<string | null>(null);
const visibleTrees = computed(() => snapshot.value?.trees.filter(tree => snapshot.value!.accessibleTreeIds ? snapshot.value!.accessibleTreeIds.includes(tree.id) : treeAccessible(tree, snapshot.value!.player, snapshot.value!.hidden?.[tree.id]?.includes(props.userId))) ?? []);
const collapsedTrees = ref(new Set<string>()), unlockNotice = ref('');
const navigationTrees = computed(() => talentTreeRows(visibleTrees.value, collapsedTrees.value));
function toggleTree(id: string) { const next = new Set(collapsedTrees.value); if (next.has(id)) next.delete(id); else next.add(id); collapsedTrees.value = next; }
function expandAncestors(id: string | null) { const next = new Set(collapsedTrees.value), seen = new Set<string>(); let tree = visibleTrees.value.find(tree => tree.id === id); while (tree?.parentTreeId && !seen.has(tree.id)) { seen.add(tree.id); next.delete(tree.parentTreeId); tree = visibleTrees.value.find(parent => parent.id === tree!.parentTreeId); } collapsedTrees.value = next; }
function selectTree(id: string) { if (!visibleTrees.value.some(tree => tree.id === id)) return; selected.value = id; nodeId.value = null; expandAncestors(id); }
watch(selected, id => expandAncestors(id));
watch(visibleTrees, (trees, before) => { if (open.value && before?.length) { const added = trees.filter(tree => !before.some(previous => previous.id === tree.id)); if (added.length) unlockNotice.value = t('talents.progression.unlockedNotice', { names: added.map(tree => tree.name).join(', ') }); else if (before.some(previous => !trees.some(tree => tree.id === previous.id))) unlockNotice.value = ''; } });
watch(visibleTrees, trees => { if (!trees.some(t => t.id === selected.value)) { selected.value = trees[0]?.id ?? null; nodeId.value = null; } expandAncestors(selected.value); }, { immediate: true });
watch(open, value => { unlockNotice.value = ''; if (value) void service.load(); });
const tree = computed(() => visibleTrees.value.find(t => t.id === selected.value));
const progress = computed(() => tree.value ? snapshot.value?.player.progress[tree.value.id] : undefined);
const node = computed(() => tree.value?.nodes.find(n => n.id === nodeId.value));
const state = computed(() => tree.value && node.value ? snapshot.value?.states[tree.value.id]?.[node.value.id] : undefined);
function investedPoints(tree: TalentTree) { return spent(snapshot.value?.player.progress[tree.id] ?? emptyTalentProgress(), tree); }
function acquiredRanks(tree: TalentTree) { return Object.values(snapshot.value?.player.progress[tree.id]?.levels ?? {}).reduce((sum, ranks) => sum + ranks.length, 0); }
function totalLevels(tree: TalentTree) { return tree.nodes.reduce((total, node) => total + node.levels.length, 0); }
function availablePoints(tree: TalentTree) { const s = snapshot.value!; return (tree.currency !== 'global' ? s.player.trees[tree.id] ?? 0 : 0) + (tree.currency !== 'tree' && s.settings.globalEnabled ? s.player.global : 0); }
function allocate(id: string) { if (tree.value && snapshot.value?.states[tree.value.id]?.[id]?.canAllocate) void service.mutate({ op: 'allocate', treeId: tree.value.id, nodeId: id }); }
function revert(id: string) { if (tree.value) void service.mutate({ op: 'revert', treeId: tree.value.id, nodeId: id }); }
function respec(specialization: boolean) { if (!tree.value || !window.confirm(t(specialization && !tree.value.options.refundSpecialization ? 'talents.burnConfirm' : 'talents.respecConfirm'))) return; void service.mutate({ op: 'respec', treeId: tree.value.id, specialization, confirm: true }); }
</script>
<style scoped lang="scss" src="@/assets/styles/features/rooms/talents/room-talents-viewer.scss"></style>
